// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 _value, address _target) public {
        vm.assume(_target != c.owner());
        vm.assume(_target.code.length == 0);
        address nonOwner = address(0x1337);
        vm.assume(nonOwner != c.owner());
        vm.deal(nonOwner, _value);
        vm.prank(nonOwner);
        bool ok;
        try c.sendMoney(_target, _value) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
